package io.github.diodeme.ji.acp.v1;

import com.agentclientprotocol.sdk.agent.PromptContext;
import com.agentclientprotocol.sdk.spec.AcpSchema;
import reactor.core.publisher.Mono;

/** ACP-v1-only reverse-RPC policy hook; domain services remain transport independent. */
@FunctionalInterface
public interface AcpV1ClientDelegate {
    Mono<Void> onPrompt(String sessionId, PromptContext client);

    static AcpV1ClientDelegate none() {
        return (sessionId, client) -> Mono.empty();
    }

    static AcpV1ClientDelegate conformanceProbe() {
        return (sessionId, client) -> client.readTextFile(new AcpSchema.ReadTextFileRequest(
                        sessionId, "conformance.txt", null, null))
                .flatMap(read -> client.writeTextFile(new AcpSchema.WriteTextFileRequest(
                        sessionId, "conformance.out", read.content())))
                .then(client.createTerminal(new AcpSchema.CreateTerminalRequest(
                        sessionId, "conformance", java.util.List.of(), null, java.util.List.of(), 1024L)))
                .flatMap(created -> client.getTerminalOutput(new AcpSchema.TerminalOutputRequest(
                                sessionId, created.terminalId()))
                        .then(client.waitForTerminalExit(new AcpSchema.WaitForTerminalExitRequest(
                                sessionId, created.terminalId())))
                        .then(client.killTerminal(new AcpSchema.KillTerminalCommandRequest(
                                sessionId, created.terminalId())))
                        .then(client.releaseTerminal(new AcpSchema.ReleaseTerminalRequest(
                                sessionId, created.terminalId()))))
                .then(client.createElicitation(AcpSchema.CreateElicitationRequest.url(
                        sessionId, "Confirm conformance", "elicitation-conformance", "https://example.invalid/confirm")))
                .then(client.completeElicitation(new AcpSchema.CompleteElicitationNotification(
                        "elicitation-conformance")));
    }
}
